TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3"},{"id":"R4","met":"yes","where":"Question 4"},{"id":"R5","met":"partial","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"partial","where":null}],"technical_issues":[{"where":"Question 1","issue":"The availability response measure, “stay up most of the time,” is not measurable; provide a quantified availability or downtime target."},{"where":"Question 3","issue":"Part (c) gives redundant payment-provider availability rather than end-to-end order-placement availability. Multiplying the redundant payment availability by the other components gives approximately 99.80% availability and 1.5 hours of monthly downtime."},{"where":"Question 5","issue":"CAP does not permit choosing consistency and availability while giving up partition tolerance in a partition. Under partition, consistency and availability are the trade-off."},{"where":"Question 6","issue":"The ADR gives no negative consequence. Retrying queue delivery until acknowledgement can also cause duplicate outlet notifications unless consumers handle duplicates."},{"where":"Question 2","issue":"The answer exceeds the 150-word limit."},{"where":null,"issue":"No assumptions are explicitly stated, as required by the assignment."}],"overall":"29/40. The scenario-specific modular-monolith recommendation and circuit-breaker explanation are strong. Marks are lost for an unmeasurable availability target, incorrect end-to-end redundancy calculation, CAP misconception, one-sided ADR consequences, an unstated assumptions section, and the Question 2 word-limit breach.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Performance and availability are relevant and justified by the lunch-hour scenario. Both scenarios include the six parts, and the performance measure is measurable. The availability measure, “most of the time,” is not quantifiable, so the scenarios do not both meet the Excellent descriptor.","evidence":[{"where":"Question 1","quote":"Response measure: the p95 response time is under 1.5 s and no requests are dropped."},{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"The modular-monolith recommendation is clear and supported by scenario-specific trade-offs involving the five-person team, single-VM load issue, and deployment downtime. The student also acknowledges the downside of shared scaling and process failure.","evidence":[{"where":"Question 2","quote":"With five developers, running eight or ten services would mean more time spent on infrastructure than on features."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Proficient","mark":5.0,"scale":8.0,"points":5.0,"max":8.0,"reasoning":"Parts (a) and (b) correctly calculate series availability and monthly downtime to the requested precision. In (c), the redundant payment availability is calculated correctly, but it is reported as end-to-end availability without multiplying by the other components. Thus exactly one part is incorrect.","evidence":[{"where":"Question 3","quote":"So the new availability of placing an order is 99.9975%, which reduces the downtime to 0.000025 × 720 = 0.018 hours, or about one minute per month."}]},{"id":"C4","level":"Excellent","mark":5.0,"scale":5.0,"points":5.0,"max":5.0,"reasoning":"The circuit breaker mechanism and states are explained correctly and applied to the slow-provider outage. The example failure threshold is a relevant tuning consideration.","evidence":[{"where":"Question 4","quote":"When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Open and calls fail immediately without waiting"},{"where":"Question 4","quote":"In the outage last month the breaker would have opened within seconds of the provider slowing down."}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"The availability choice for browsing and consistency choice for payment are reasonable, and concrete techniques are named. However, the CAP explanation is incorrect: during a partition, a system cannot retain both consistency and availability; it must trade one off. This is a significant imprecision.","evidence":[{"where":"Question 5","quote":"To be safe on retries, each order request carries an idempotency key so that a repeated request does not create a second charge."},{"where":"Question 5","quote":"To be safe on retries, each order request carries an idempotency key so that a repeated request does not create a second charge."}]},{"id":"C6","level":"Proficient","mark":3.0,"scale":5.0,"points":3.0,"max":5.0,"reasoning":"Context, decision, and consequences are present and specific to the scenario. Consequences list only benefits, with no negative consequence such as added queue operations or possible duplicate notifications on retry.","evidence":[{"where":"Question 6","quote":"Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"The required headings and numbered citations with a reference list are used, and terminology is generally clear. Question 2 is approximately 181 words, exceeding the 150-word limit; this fits the Proficient descriptor.","evidence":[{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]}]}
